<div class="patient-page-heading"><div><span class="eyebrow text-secondary">PLANIFICA TU ATENCIÓN</span><h1>Consultar disponibilidad</h1><p class="text-secondary mb-0">Franjas calculadas con horarios, bloqueos y citas existentes.</p></div></div>
<form method="get" action="<?= $escape($base) ?>/disponibilidad" class="patient-card patient-form"><div class="row g-3"><div class="col-md-4"><label class="form-label" for="medico">Médico *</label><select class="form-select" name="medico" id="medico" required><option value="">Seleccionar</option><?php foreach($choices['doctors'] as $m): ?><option value="<?= $escape($m['id_medico']) ?>" <?= (string)$doctor===(string)$m['id_medico'] ? 'selected' : '' ?>><?= $escape($m['nombre']) ?><?= $m['estado']==='inactivo' ? ' (inactivo)' : '' ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label" for="especialidad">Especialidad *</label><select class="form-select" id="especialidad" name="especialidad" required><option value="">Seleccionar</option><?php foreach($choices['specialties'] as $e): ?><option value="<?= $escape($e['id_especialidad']) ?>" <?= (string)$specialty===(string)$e['id_especialidad'] ? 'selected' : '' ?>><?= $escape($e['nombre']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label" for="fecha">Fecha *</label><input class="form-control" type="date" name="fecha" id="fecha" value="<?= $escape($date) ?>" required></div></div>
<?php if($result): ?><p class="text-secondary small mt-4">Referencia: <?= $escape($result['window'][0].' a '.$result['window'][9]) ?> · America/La_Paz</p><div class="alert alert-info" role="status"><?= $escape($result['message']) ?></div>
<?php if($result['selected']): ?><div class="alert alert-success" role="status">Franja consultada: <?= $escape($result['selected']['hora_inicio'].'–'.$result['selected']['hora_fin']) ?>. No se ha realizado ninguna reserva.<?php if(\Clinica\Middleware\BookingAccess::allowed($user)): ?><div class="mt-3"><a class="btn btn-clinic" href="<?= $escape($base.'/reservar?'.http_build_query(['medico'=>$doctor,'especialidad'=>$specialty,'fecha'=>$date,'hora'=>$result['selected']['hora_inicio']])) ?>">Continuar a reserva →</a></div><?php endif; ?></div><?php endif; ?>
<div class="appointment-slots"><?php foreach($result['slots'] as $slot): ?><label class="appointment-slot <?= $slot['available'] ? 'slot-disponible' : (str_contains($slot['estado'],'ocupada') ? 'slot-ocupada' : ($slot['estado']==='bloqueada' ? 'slot-bloqueada' : 'slot-pasada')) ?>" data-available="<?= $slot['available'] ? 'true' : 'false' ?>"><input type="radio" name="hora" value="<?= $escape($slot['hora_inicio']) ?>" <?= $slot['available'] ? '' : 'disabled' ?> <?= $time===$slot['hora_inicio'] && $slot['available'] ? 'checked' : '' ?>><span><strong><?= $escape(\Clinica\Services\ScheduleValidator::displayTime($slot['hora_inicio']).'–'.\Clinica\Services\ScheduleValidator::displayTime($slot['hora_fin'])) ?></strong><small><?= $escape(ucfirst($slot['estado'])) ?></small></span></label><?php endforeach; ?></div><?php endif; ?>
<div class="patient-form-actions"><button class="btn btn-clinic" type="submit">Consultar disponibilidad</button></div></form><p class="text-secondary small mt-3">La disponibilidad puede cambiar mientras consultas. Esta pantalla no guarda citas ni retiene turnos.</p>
